use password_manager::types::ServerCommand;
use serde::Deserialize;

#[derive(Deserialize)]
struct Fixture {
    command: serde_json::Value,
    messagepack: String,
}

#[test]
fn command_indices_and_positional_fields_match_fixed_wire_fixtures() {
    // These are checked-in bytes, not regenerated by the test. Existing
    // variants and fields must retain their positions for installed clients.
    let fixtures: Vec<Fixture> =
        serde_json::from_str(include_str!("fixtures/server_commands.json")).unwrap();
    for fixture in fixtures {
        let command: ServerCommand = serde_json::from_value(fixture.command.clone()).unwrap();
        let expected = hex::decode(&fixture.messagepack).unwrap();
        assert_eq!(rmp_serde::to_vec(&command).unwrap(), expected);
        let decoded: ServerCommand = rmp_serde::from_slice(&expected).unwrap();
        assert_eq!(serde_json::to_value(decoded).unwrap(), fixture.command);
    }
}
